CREATE TABLE video_shares (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),video_id UUID NOT NULL REFERENCES videos(id) ON DELETE CASCADE,token_hash CHAR(64) NOT NULL UNIQUE,created_by UUID NOT NULL REFERENCES users(id),expires_at TIMESTAMPTZ,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE video_comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),video_id UUID NOT NULL REFERENCES videos(id) ON DELETE CASCADE,author_user_id UUID NOT NULL REFERENCES users(id),body VARCHAR(4000) NOT NULL CHECK(length(trim(body))>0),timestamp_seconds INTEGER CHECK(timestamp_seconds IS NULL OR timestamp_seconds>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE INDEX video_comments_video_created_idx ON video_comments(video_id,created_at);
CREATE TABLE playback_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),video_id UUID NOT NULL REFERENCES videos(id) ON DELETE CASCADE,workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,event_type VARCHAR(30) NOT NULL CHECK(event_type IN ('PLAY','PAUSE','COMPLETE','ERROR')),watched_seconds INTEGER NOT NULL DEFAULT 0 CHECK(watched_seconds>=0),viewer_fingerprint_hash CHAR(64),occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX playback_events_workspace_date_idx ON playback_events(workspace_id,occurred_at DESC);
